insert into public.residencies (
  source_order,
  acgme_id,
  program_name,
  specialty,
  city,
  state,
  location_filter_key,
  specialty_filter_key,
  accepting_applications,
  source_last_updated,
  research_date,
  program_length_years,
  first_year_positions,
  program_size,
  avg_work_hours,
  program_setting,
  application_service,
  about_program,
  notable_features,
  interview_format,
  interviews_last_year,
  interviews_per_first_year_position,
  img_step1_required,
  img_step2_required,
  medical_school_graduation_within_years,
  gap_experience_requirement,
  j1_sponsorship,
  h1b_sponsorship,
  f1_opt_first_year,
  visa_friendliness,
  visa_filter_ready,
  moonlighting_beyond_pgy1,
  night_float,
  structured_didactics_hours,
  research_rotation,
  source_type,
  source_url,
  verification_status,
  current_information_warning
)
select
  source_order::smallint,
  acgme_id,
  program_name,
  specialty,
  city,
  state,
  location_filter_key,
  specialty_filter_key,
  accepting_applications::boolean,
  source_last_updated,
  research_date::date,
  program_length_years::smallint,
  first_year_positions,
  program_size::smallint,
  avg_work_hours::numeric,
  program_setting,
  application_service,
  about_program,
  notable_features,
  interview_format,
  interviews_last_year::smallint,
  interviews_per_first_year_position::numeric,
  img_step1_required,
  img_step2_required,
  medical_school_graduation_within_years,
  gap_experience_requirement,
  j1_sponsorship,
  h1b_sponsorship,
  f1_opt_first_year,
  visa_friendliness,
  visa_filter_ready::boolean,
  moonlighting_beyond_pgy1,
  night_float,
  structured_didactics_hours,
  research_rotation,
  source_type,
  source_url,
  verification_status,
  current_information_warning
from raw_rows
on conflict (acgme_id) do update set
  source_order = excluded.source_order,
  program_name = excluded.program_name,
  specialty = excluded.specialty,
  city = excluded.city,
  state = excluded.state,
  location_filter_key = excluded.location_filter_key,
  specialty_filter_key = excluded.specialty_filter_key,
  accepting_applications = excluded.accepting_applications,
  source_last_updated = excluded.source_last_updated,
  research_date = excluded.research_date,
  program_length_years = excluded.program_length_years,
  first_year_positions = excluded.first_year_positions,
  program_size = excluded.program_size,
  avg_work_hours = excluded.avg_work_hours,
  program_setting = excluded.program_setting,
  application_service = excluded.application_service,
  about_program = excluded.about_program,
  notable_features = excluded.notable_features,
  interview_format = excluded.interview_format,
  interviews_last_year = excluded.interviews_last_year,
  interviews_per_first_year_position = excluded.interviews_per_first_year_position,
  img_step1_required = excluded.img_step1_required,
  img_step2_required = excluded.img_step2_required,
  medical_school_graduation_within_years = excluded.medical_school_graduation_within_years,
